-- 5. 演示对话记录（简化版，约10条）
INSERT INTO interview_message (id, session_id, role, content, phase, depth) VALUES('m0000000-0000-0000-0000-000000000001', 'i0000000-0000-0000-0000-000000000001', 'ai', '请回忆过去半年里，你搞定过的最难的一个客户。化名就好，难在哪？', 'opening', 0),('m0000000-0000-0000-0000-000000000002', 'i0000000-0000-0000-0000-000000000001', 'user', '瑞丰银行，一家城商行。他们想换核心结算系统。难在科技部吴总和竞品A关系特别好，我前期门都进不去。', 'opening', 0),('m0000000-0000-0000-0000-000000000003', 'i0000000-0000-0000-0000-000000000001', 'ai', '门都进不去——这个开局很艰难。你做的第一件事是什么？', 'storytelling', 0),('m0000000-0000-0000-0000-000000000004', 'i0000000-0000-0000-0000-000000000001', 'user', '我查了他近三次公开讲话。把稿子打印出来，用荧光笔标出了他反复提的三个词：监管合规、安全可控、不想当小白鼠。', 'storytelling', 0),('m0000000-0000-0000-0000-000000000005', 'i0000000-0000-0000-0000-000000000001', 'ai', '你看到了什么让你得出这个判断？', 'storytelling', 1),('m0000000-0000-0000-0000-000000000006', 'i0000000-0000-0000-0000-000000000001', 'user', '他57岁了。那篇专访里他说“在退休之前，把行里的科技底座夯实，不给继任者留坑”。我判断：这个人不要政绩，要的是不出事。', 'storytelling', 1),('m0000000-0000-0000-0000-000000000007', 'i0000000-0000-0000-0000-000000000001', 'ai', '如果把你刚才的做法总结成几个核心步骤，你会怎么分？每一步叫什么名字？', 'modeling', 0),('m0000000-0000-0000-0000-000000000008', 'i0000000-0000-0000-0000-000000000001', 'user', '我想想…叫“透视”吧。第一步画像先行，第二步价值敲门，第三步承诺体验，第四步钩子延伸。', 'modeling', 0),('m0000000-0000-0000-0000-000000000009', 'i0000000-0000-0000-0000-000000000001', 'ai', '你这套方法，对什么样的客户或场景绝对不管用？', 'closing', 0),('m0000000-0000-0000-0000-000000000010', 'i0000000-0000-0000-0000-000000000001', 'user', '客户自己不决策，只是个传声筒的；或者项目已经内定了的。', 'closing', 0);
-- 6. 演示报告
INSERT INTO report (id, space_id, session_id, title, subtitle, content_json, file_status, rating, view_count) VALUES('r0000000-0000-0000-0000-000000000001', 's0000000-0000-0000-0000-000000000001', 'i0000000-0000-0000-0000-000000000001', '透视', '在复杂决策链中找到并搞定关键人', '{  "chapters": [    {"order": 1, "title": "案例故事", "content": "瑞丰银行，一家城商行..."},    {"order": 2, "title": "方法论：透视四步法", "steps": [      {"order": 1, "name": "画像先行", "action": "接触前彻底研究人", "script": "无口头话术", "mistake": "只研究职位不研究人"},      {"order": 2, "name": "价值敲门", "action": "制作无法拒绝的钩子", "script": "我整理了一份《结算系统迁移的七个坑》，寄给您。如果没用，就当废纸扔掉。", "mistake": "空手上门"},      {"order": 3, "name": "承诺体验", "action": "展示功课+坦诚+守时", "script": "您划红线的点，我们从那里直接开始。", "mistake": "拼命展示自己"},      {"order": 4, "name": "钩子延伸", "action": "从单线变成网状扎根", "script": "您能否安排运营部提供前5个痛点？", "mistake": "只吊在老大一棵树上"}    ]},    {"order": 3, "title": "关键决策点分析", "decisions": [      {"title": "门都进不去，走哪条路？", "options": ["继续托人", "绕过", "研究这个人"], "chosen": "研究这个人", "reason": "他怕的不是花钱，是出事"}    ]},    {"order": 4, "title": "专家心法", "quotes": ["恐惧的驱动力远大于贪婪", "不是在卖药，是在开方子"], "oneliner": "不是在卖药，是在开方子", "metaphor": "像医生看X光片"},    {"order": 5, "title": "避坑指南", "pitfalls": [{"title": "只研究职位不研究人", "solution": "画像先行"}]},    {"order": 6, "title": "行动检查清单与情景练习", "practice_scene": {"title": "第一次见银行客户", "setting": "你是销售，我是瑞丰银行科技部吴总", "customerLine": "已经有两家在谈，不考虑新的"}}  ]}', 'synced', 4.9, 1256);
